def newman_prime(n):
    """Return the nth Newman-Shanks-Williams number.

    Uses 0-based indexing with S(0)=1, S(1)=1 and
    S(n)=2*S(n-1)+S(n-2), so S(3)==7.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0 or n == 1:
        return 1
    a, b = 1, 1
    for _ in range(2, n + 1):
        a, b = b, 2 * b + a
    return b
